    "usage": "import { GlassReveal } from \"@/registry/ui/glass-reveal\";\n\nexport function GlassRevealDemo() {\n  return (\n    <div className=\"w-full flex items-center justify-center p-8\">\n      <GlassReveal\n        image=\"/images/sunflowers.jpg\"\n        shape=\"circle\"\n        size={0.70}\n        softness={0.00}\n        distortion={0.45}\n        aberration={0.000}\n        wobble={0.00}\n        wobbleSpeed={1.5}\n        waveFrequency={1}\n        waveStrength={0.000}\n        waveSpeed={0.1}\n        grain={0.020}\n        grainSpeed={22}\n        grayscale={0.85}\n        dim={0.00}\n        follow={0.00}\n        returnToCenter={false}\n        fallback=\"#171717\"\n        paused={false}\n      />\n    </div>\n  );\n}",
