    "usage": "import { ContourTide } from \"@/components/contour-tide\";\n\nexport default function HeroSection() {\n  return (\n    <div className=\"relative w-full h-[520px] rounded-2xl overflow-hidden border border-white/10\">\n      <ContourTide\n        preset=\"silver\"\n        density={1.0}\n        waveHeight={1.0}\n        choppiness={0.8}\n        interactive={true}\n        clickRipples={true}\n      >\n        <div className=\"relative z-10 flex flex-col items-center justify-center h-full text-center px-4\">\n          <span className=\"text-xs font-mono uppercase tracking-widest text-white/60 mb-2\">\n            Dynamic Fluid Field\n          </span>\n          <h1 className=\"text-4xl sm:text-5xl font-bold text-white tracking-tight\">\n            Contour Tide\n          </h1>\n          <p className=\"text-sm sm:text-base text-white/70 max-w-md mt-2\">\n            An ocean of particles rolling in waves with interactive swells and click ripples.\n          </p>\n        </div>\n      </ContourTide>\n    </div>\n  );\n}",
